using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Markup;

namespace WindowWise.Localization;

/// <summary>Live catalog bindings for XAML and messages generated by code.</summary>
[MarkupExtensionReturnType(typeof(string))]
public sealed class TExtension : MarkupExtension
{
    public string Key { get; set; } = "";
    public TExtension() { }
    public TExtension(string key) => Key = key;
    public override object ProvideValue(IServiceProvider serviceProvider) =>
        UiText.CreateBinding(new LocalizedMessage(AppText.Source(Key))).ProvideValue(serviceProvider);
}

/// <summary>Translate an enum/fallback or a formatted label while preserving the bound user's value.</summary>
public sealed class DisplayBindingExtension : MarkupExtension
{
    public string Path { get; set; } = "";
    public string? Format { get; set; }
    public string? Fallback { get; set; }
    public bool TranslateValue { get; set; }
    public override object ProvideValue(IServiceProvider serviceProvider)
    {
        var binding = new MultiBinding { Converter = new DisplayConverter(this), Mode = BindingMode.OneWay };
        binding.Bindings.Add(new Binding(Path));
        binding.Bindings.Add(new Binding(nameof(AppText.Language)) { Source = AppText.Current });
        return binding.ProvideValue(serviceProvider);
    }
    private sealed class DisplayConverter(DisplayBindingExtension settings) : IMultiValueConverter
    {
        public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
        {
            object? value = values[0] == DependencyProperty.UnsetValue ? null : values[0];
            string display = value?.ToString() ?? UiText.Text(settings.Fallback ?? "");
            if (settings.TranslateValue && value is not null)
                display = UiText.Text(display == "NotPresent" ? "Not present" : display);
            return settings.Format is null ? display : UiText.Text(AppText.Source(settings.Format), display);
        }
        public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture) =>
            throw new NotSupportedException();
    }
}

public static class UiText
{
    private static readonly MessageConverter Converter = new();
    public static Binding CreateBinding(LocalizedMessage message) => new(nameof(AppText.Language))
    {
        Source = AppText.Current, Mode = BindingMode.OneWay,
        Converter = Converter, ConverterParameter = message
    };
    public static string Text(string source, params object[] arguments) => AppText.Current.Text(source, arguments);
    public static LocalizedMessage Message(string source, params object[] arguments) => new(source, arguments);
    public static void SetText(TextBlock target, LocalizedMessage message) =>
        BindingOperations.SetBinding(target, TextBlock.TextProperty, CreateBinding(message));
    public static void SetContent(ContentControl target, LocalizedMessage message) =>
        BindingOperations.SetBinding(target, ContentControl.ContentProperty, CreateBinding(message));
    public static void SetToolTip(FrameworkElement target, LocalizedMessage message) =>
        BindingOperations.SetBinding(target, FrameworkElement.ToolTipProperty, CreateBinding(message));

    private sealed class MessageConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture) => parameter.ToString()!;
        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) => Binding.DoNothing;
    }
}
